 {section==='content'&&<><div className="toolbar-end"><button className="button dark" onClick={()=>open('content')}><Plus size={17}/>{translate('portal','content_edit')}</button></div><section className="panel"><div className="panel-heading"><div><h2>{translate('portal','content_pages_title')}</h2><p className="muted">{translate('portal','content_pages_hint')}</p></div><Link className="text-link" href={`${base}/website`}>{translate('portal','content_open_website')}</Link></div><Table rows={d.pages??[]} columns={[{key:'slug',title:translate('portal','content_col_page')},{key:'title',title:translate('portal','content_col_title')},{key:'published',title:translate('portal','enquiry_status_label'),render:r=><Badge status={r.published?'published':'draft'}/>},{key:'action',title:'',render:r=><button className="text-link" onClick={()=>open('content',r)}>{translate('portal','content_edit_row')}</button>}]} empty={translate('portal','content_empty_title')} emptyBody={translate('portal','content_empty_body')}/></section></>}
